const config=window.SUNDAR_CONFIG;
const demoData=window.SUNDAR_DEMO_DATA;
const phone=config.whatsappNumber;
const categories=demoData.categories;
const products=demoData.products;
let selected='All',expanded=false;
const filters=document.querySelector('#categoryFilters'),grid=document.querySelector('#productGrid');
function renderFilters(){filters.innerHTML=categories.map((c,i)=>`<button class="category-card ${c===selected?'active':''}" data-category="${c}"><span class="category-icon">${['✦','❈','◉','✤','◆','▣','⬡'][i]}</span><strong>${c}</strong></button>`).join('');}
function renderProducts(){const list=products.filter(p=>selected==='All'||p.category===selected);grid.innerHTML=(expanded?list:list.slice(0,4)).map(p=>`<article class="product-card" tabindex="0" data-id="${p.id}"><div class="product-image" style="--image:url('assets/emerald-saree.png');--tint:${p.tint}"></div><div class="product-body"><small>${p.category}</small><h3>${p.name}</h3><div class="product-meta"><span>${p.price}</span><span>${p.days}</span></div></div></article>`).join('')||'<p>No designs in this category yet.</p>';}
filters.addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;selected=b.dataset.category;expanded=true;renderFilters();renderProducts();document.querySelector('#designs').scrollIntoView();});
document.querySelector('#showAll').onclick=()=>{selected='All';expanded=true;renderFilters();renderProducts()};
function openProduct(id){const p=products.find(x=>x.id===+id),msg=encodeURIComponent(`Hello Sundar Embroidery Works, I am interested in ${p.name}. Please share price and details.`);document.querySelector('#productDetail').innerHTML=`<img class="detail-image" src="assets/emerald-saree.png" alt="${p.name}"><div class="detail-content"><p class="eyebrow">${p.category}</p><h2>${p.name}</h2><p>Production estimate: ${p.days}<br>${p.bulk?'Bulk orders available':'Individual custom orders available'}</p><p>Final pricing depends on fabric, dimensions, thread choice and design complexity.</p><a class="button primary" target="_blank" rel="noopener" href="https://wa.me/${phone}?text=${msg}">Enquire on WhatsApp</a></div>`;document.querySelector('#productDialog').showModal()}
grid.addEventListener('click',e=>{const c=e.target.closest('[data-id]');if(c)openProduct(c.dataset.id)});grid.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.id)openProduct(e.target.dataset.id)});
document.querySelector('.dialog-close').onclick=()=>document.querySelector('#productDialog').close();
document.querySelector('#checkPincode').onclick=()=>{const v=document.querySelector('#pincode').value.trim(),r=document.querySelector('#pincodeResult');if(!/^\d{6}$/.test(v)){r.textContent='Please enter a valid 6-digit pincode.';r.className='error';return}r.textContent='Thanks! Contact our team to confirm service and delivery for '+v+'.';r.className=''};
document.querySelector('#bulkForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),msg=`Hello Sundar Embroidery Works, I need a bulk quote.\nProduct: ${d.get('productType')}\nQuantity: ${d.get('quantity')}\nName: ${d.get('name')}\nMobile: ${d.get('mobile')}\nPincode: ${d.get('deliveryPincode')}\nRequired date: ${d.get('requiredDate')}\nRequirements: ${d.get('requirements')||'Not specified'}`;window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank','noopener')};
document.querySelector('#trackButton').onclick=()=>{const v=document.querySelector('#orderNumber').value.trim(),r=document.querySelector('#trackResult');if(!v){r.innerHTML='<p class="error">Please enter your order number.</p>';return}r.innerHTML=`<p class="notice">Demo tracking for <b>${v}</b></p><div class="timeline"><span class="done">Order confirmed</span><span class="done">Design finalized</span><span>In production</span><span>Quality check</span><span>Ready / dispatched</span><span>Delivered</span></div>`};
document.querySelector('#year').textContent=new Date().getFullYear();renderFilters();renderProducts();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');
